package main

import (
	"io"
	"net/http"
)

// serveWirelloDemoLogin renders the public-facing demo entry screen. Credentials
// are intentionally prefilled because this account is a synthetic, read-only
// prospect demo and is scoped by the gateway to the Wirello profile only.
func serveWirelloDemoLogin(w http.ResponseWriter, r *http.Request) {
	errMsg := ""
	if r.URL.Query().Get("error") != "" {
		errMsg = `<div class="error">Входът не беше успешен. Натиснете отново „Вход в Навигатор“.</div>`
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
	io.WriteString(w, `<!doctype html><html lang="bg"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wirello Market — BLIS Navigator Demo</title><style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Inter,Segoe UI,Arial,sans-serif;color:#102f3a}body{min-height:100vh;display:grid;place-items:center;padding:28px;background:radial-gradient(circle at 78% 18%,rgba(36,142,126,.16),transparent 34%),linear-gradient(135deg,#f9fcfb 0%,#edf6f3 58%,#e7f1ee 100%)}.wrap{width:min(100%,520px)}.brand{text-align:center;margin-bottom:20px}.brand strong{display:block;font:700 34px/1 Georgia,serif;color:#123c45}.brand span{display:block;margin-top:7px;font-size:10px;letter-spacing:.15em;text-transform:uppercase;color:#6a7f83}.card{overflow:hidden;background:#fff;border:1px solid #dce8e5;border-radius:22px;box-shadow:0 28px 80px rgba(20,62,66,.16)}.clienthero{position:relative;padding:28px 30px 24px;background:linear-gradient(120deg,#0d5f61 0%,#147a6d 55%,#2d9d7f 100%);color:#fff}.clienthero:after{content:"";position:absolute;right:-45px;top:-60px;width:210px;height:210px;border-radius:50%;border:1px solid rgba(255,255,255,.18);box-shadow:0 0 0 32px rgba(255,255,255,.04),0 0 0 68px rgba(255,255,255,.035)}.eyebrow{position:relative;z-index:1;font-size:9px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;opacity:.76}.clienthero h1{position:relative;z-index:1;margin:8px 0 6px;font:600 32px/1.05 Georgia,serif}.clienthero p{position:relative;z-index:1;margin:0;font-size:12px;opacity:.84}.demo{position:relative;z-index:1;display:inline-flex;align-items:center;gap:7px;margin-top:16px;padding:7px 10px;border:1px solid rgba(255,255,255,.3);border-radius:999px;font-size:9px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;background:rgba(255,255,255,.08)}.demo i{width:7px;height:7px;border-radius:50%;background:#83f0a9;box-shadow:0 0 0 4px rgba(131,240,169,.12)}.body{padding:27px 30px 30px}.body h2{margin:0 0 6px;font-size:18px;color:#143f47}.sub{margin:0 0 20px;color:#6c7f83;font-size:12px;line-height:1.55}.field{margin:0 0 14px}.field label{display:block;margin-bottom:7px;font-size:9px;font-weight:850;letter-spacing:.08em;text-transform:uppercase;color:#587075}.field input{width:100%;height:48px;padding:0 13px;border:1px solid #d4e2df;border-radius:10px;background:#f7faf9;color:#173f45;font-size:14px;font-weight:650;outline:none}.field input:focus{border-color:#2d8c7d;box-shadow:0 0 0 3px rgba(45,140,125,.12);background:#fff}.hint{font-size:9px;color:#829397;margin-top:5px}.enter{width:100%;height:52px;margin-top:7px;border:0;border-radius:10px;background:#123f47;color:#fff;font-size:13px;font-weight:850;cursor:pointer;box-shadow:0 10px 24px rgba(18,63,71,.18)}.enter:hover{background:#0f5660}.error{margin:0 0 15px;padding:10px 12px;border-radius:9px;background:#fff2f2;border:1px solid #efcdcd;color:#a13f3f;font-size:11px}.safe{display:flex;justify-content:center;align-items:center;gap:7px;margin-top:17px;color:#829397;font-size:9px}.safe i{width:6px;height:6px;border-radius:50%;background:#50ae77}.foot{text-align:center;margin-top:15px;color:#71878b;font-size:10px}.foot a{color:#466e73;text-decoration:none}</style></head><body><div class="wrap"><div class="brand"><strong>BLIS™</strong><span>Brand Lab Intelligence System</span></div><div class="card"><div class="clienthero"><div class="eyebrow">Демонстрационен клиентски профил</div><h1>Wirello Market</h1><p>Omnichannel Retail Network · MASTER DEMO</p><div class="demo"><i></i> Synthetic demonstration data</div></div><div class="body"><h2>Клиентски достъп</h2><p class="sub">Данните за демонстрационния профил са заредени. Натиснете бутона, за да влезете в BLIS Navigator.</p>`+errMsg+`<form method="post" action="/api/client-login" autocomplete="off"><div class="field"><label for="username">Потребителско име</label><input id="username" name="username" type="text" value="wirello.demo" readonly required><div class="hint">Демонстрационен потребител</div></div><div class="field"><label for="password">Парола</label><input id="password" name="password" type="text" value="BLISdemo2026!" readonly required><div class="hint">Демонстрационна парола</div></div><button class="enter" type="submit">Вход в Навигатор</button></form><div class="safe"><i></i> Достъпът е ограничен само до Wirello Market</div></div></div><div class="foot"><a href="/">← Към началната страница</a></div></div></body></html>`)
}
